import{_ as i,o as e,c as t,a2 as r}from"./chunks/framework.BXA5Pi9t.js";const p=JSON.parse('{"title":"Ceph Performance Meeting 2021-08-26","description":"","frontmatter":{"title":"Ceph Performance Meeting 2021-08-26","date":"2021-08-26T00:00:00.000Z","updated":"2021-08-27T00:00:00.000Z","tags":["Ceph","性能优化","分布式存储","调试工具","自动化测试"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2021/Ceph_Performance_Meeting_2021-08-26.md","filePath":"posts/2021/Ceph_Performance_Meeting_2021-08-26.md","lastUpdated":1780459816000}'),o={name:"posts/2021/Ceph_Performance_Meeting_2021-08-26.md"};function a(n,l,s,g,h,u){return e(),t("div",null,[...l[0]||(l[0]=[r('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="关键细节" tabindex="-1">关键细节 <a class="header-anchor" href="#关键细节" aria-label="Permalink to &quot;关键细节&quot;">​</a></h4><ul><li><strong>会议时间</strong>: 2021年8月26日</li><li><strong>参会人员</strong>: 核心团队成员及部分研发人员</li><li><strong>会议主持</strong>: 未明确指出</li></ul><h4 id="讨论的主要议题" tabindex="-1">讨论的主要议题 <a class="header-anchor" href="#讨论的主要议题" aria-label="Permalink to &quot;讨论的主要议题&quot;">​</a></h4><ol><li><p><strong>新PR审查</strong>:</p><ul><li><strong>Prometheus缓存禁用</strong>: 讨论了针对小型部署禁用Prometheus缓存的功能，可能涉及内存使用问题。</li><li><strong>Direct IO写入方式变更</strong>: Adam提出了一个草案PR，旨在改变Direct IO写入方式，以确保安全性并提升性能。</li><li><strong>RGW跟踪实现</strong>: 讨论了RGW跟踪实现的关闭，以及后续的跟踪扩展和细节添加。</li></ul></li><li><p><strong>已关闭PR</strong>:</p><ul><li><strong>RGW缓存问题</strong>: 讨论了RGW缓存的相关问题，包括缓存的必要性和可能的改进。</li><li><strong>BlueStore cap omap命名方案升级</strong>: Igor解释了该PR的目的，即解决大型引用写入时的性能问题。</li></ul></li><li><p><strong>性能调查和未来计划</strong>:</p><ul><li><strong>性能调查工具</strong>: 讨论了性能调查工具的需求，如Kubernetes性能测试工具Storms，以及如何在上游进行测试。</li><li><strong>平衡改进</strong>: 讨论了平衡改进的必要性，特别是在处理大量小文件时的性能问题。</li><li><strong>QoS和缓存策略</strong>: 讨论了QoS的一般性问题，以及如何改进缓存策略以更好地平衡资源。</li></ul></li><li><p><strong>特定组件的性能问题</strong>:</p><ul><li><strong>RGW和CephFS</strong>: 讨论了RGW和CephFS中的多个性能问题，包括缓存管理、异步请求处理和多站点性能。</li><li><strong>RBD</strong>: 讨论了RBD的客户端持久缓存问题，以及NVMe或Fabric网关的潜在性能影响。</li></ul></li><li><p><strong>其他议题</strong>:</p><ul><li><strong>自动化性能测试</strong>: 讨论了自动化性能测试的需求和挑战，以及如何确保性能不会在代码更新中退化。</li></ul></li></ol><h4 id="决定的事项" tabindex="-1">决定的事项 <a class="header-anchor" href="#决定的事项" aria-label="Permalink to &quot;决定的事项&quot;">​</a></h4><ul><li>需要进一步审查和讨论Prometheus缓存禁用的PR。</li><li>Adam将继续审查和改进Direct IO写入方式的PR。</li><li>需要进一步讨论和实施RGW跟踪的扩展和细节添加。</li><li>需要关注和改进平衡性能，特别是在处理大量小文件时。</li><li>需要进一步研究和实施QoS和缓存策略的改进。</li><li>需要关注RGW和CephFS中的多个性能问题，并寻找解决方案。</li><li>需要关注RBD的客户端持久缓存问题，并评估NVMe或Fabric网关的性能影响。</li><li>需要进一步讨论和实施自动化性能测试，以确保性能不会在代码更新中退化。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ul><li>继续审查和讨论Prometheus缓存禁用的PR。</li><li>继续审查和改进Direct IO写入方式的PR。</li><li>继续讨论和实施RGW跟踪的扩展和细节添加。</li><li>继续关注和改进平衡性能，特别是在处理大量小文件时。</li><li>继续研究和实施QoS和缓存策略的改进。</li><li>继续关注RGW和CephFS中的多个性能问题，并寻找解决方案。</li><li>继续关注RBD的客户端持久缓存问题，并评估NVMe或Fabric网关的性能影响。</li><li>继续讨论和实施自动化性能测试，以确保性能不会在代码更新中退化。</li></ul><h4 id="其他备注" tabindex="-1">其他备注 <a class="header-anchor" href="#其他备注" aria-label="Permalink to &quot;其他备注&quot;">​</a></h4><ul><li>会议中提到了多个具体的PR和代码变更，这些需要研发团队的具体成员进行跟进和实施。</li><li>会议中提到了多个性能调查工具和方法，这些需要进一步的研究和实施。</li><li>会议中提到了多个具体的性能问题，这些需要进一步的讨论和解决方案。</li><li>会议中提到了自动化性能测试的需求和挑战，这些需要进一步的讨论和实施。</li></ul>',11)])])}const d=i(o,[["render",a]]);export{p as __pageData,d as default};
